import logging
import queue
from datetime import datetime


python_logger = logging.getLogger("AdminApiLogger")
python_logger.addHandler(logging.NullHandler())


class AdminApiLogMessage:

    def __init__(self, msg, level):
        self.msg = msg
        self.level = level
        self.timestamp = datetime.now()

    def __str__(self):
        return "{} {}".format(self.timestamp, self.msg)


class AdminApiLogger:

    INFO = logging.INFO
    DEBUG = logging.DEBUG
    WARN = logging.WARNING
    ERROR = logging.ERROR

    def __init__(self):
        self.buffer = queue.Queue()
        self.buffering = False
        self.trim_logs = False
        self.max_length = None

    def debug(self, msg):
        """Log debug message."""
        self.log(msg, self.DEBUG)

    def info(self, msg):
        """Log info message."""
        self.log(msg, self.INFO)

    def warning(self, msg):
        """Log warn message."""
        self.log(msg, self.WARN)

    def error(self, msg):
        """Log error message."""
        self.log(msg, self.ERROR)

    def log(self, msg, level=INFO):
        """Log message."""
        if self.trim_logs:
            if len(msg) > self.max_length:
                msg = msg[:self.max_length] + "..."
        if self.buffering:
            self.buffer.put(AdminApiLogMessage(msg, level))
        else:
            python_logger.log(level, msg)

    def enable_buffering(self):
        """Enable message buffering."""
        self._clear_buffer()
        self.buffering = True

    def disable_buffering(self):
        """Disable message buffering."""
        self.buffering = False

    def flush(self):
        """Flush message buffer."""
        while not self.buffer.empty():
            msg = self.buffer.get()
            python_logger.log(msg.level, msg)

    def _clear_buffer(self):
        with self.buffer.mutex:
            self.buffer.queue.clear()

    def enable_trimming(self, max_length=60):
        self.trim_logs = True
        self.max_length = max_length


logger = AdminApiLogger()
